3	namespace App\Http\Controllers\Api\Internal;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Models\Core\Professional\BrandPartnerLink;
7	use App\Models\Core\Professional\Professional;
8	use App\Models\Core\Professional\ProfessionalIntegration;
9	use App\Models\Core\Professional\Service;
10	use App\Models\Core\Site\Block;
11	use App\Models\Core\Site\Site;
12	use App\Models\Core\Site\SiteMedia;
13	use Illuminate\Http\JsonResponse;
14	use Illuminate\Http\Request;
15	use Illuminate\Support\Facades\Validator;
16	use Illuminate\Validation\ValidationException;
17	
18	// V2: Internal endpoint for Hydrogen loaders. Validates an affiliate slug belongs to
19	// a brand and returns the affiliate's full sitepage payload: gallery, content images,
20	// every link category (social + content + education + events + custom + synthesized
21	// booking), bio + about, document, newsletter, services, and booking.
22	//
23	// Every section that has a Draft/Live toggle in the dashboard is returned as an
24	// envelope `{state: "draft"|"live", data: <payload>|null}`. Hydrogen reads `state`
25	// to decide whether to mount the section; `data` is always null when draft so draft
26	// content never leaks publicly even if Hydrogen has a bug. Per-row Draft/Live (links)
27	// is handled server-side: is_active=false rows are simply filtered out.
28	class HydrogenAffiliateController extends ApiController
29	{
30	    public function show(Request $request): JsonResponse
31	    {
32	        $validator = Validator::make($request->query(), [
33	            'shop_domain' => ['required', 'string', 'max:255'],
34	            'slug' => ['required', 'string', 'max:255'],
35	        ]);
36	
37	        if ($validator->fails()) {
38	            throw new ValidationException($validator);
39	        }
40	
41	        $validated = $validator->validated();
42	        $shopDomain = strtolower(trim($validated['shop_domain']));
43	        $slug = strtolower(trim($validated['slug']));
44	
45	        $integration = ProfessionalIntegration::query()
46	            ->where('shopify_shop_domain', $shopDomain)
47	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
48	            ->first();
49	
50	        if (! $integration) {
51	            return $this->error('Brand not found.', 404);
52	        }
53	
54	        $affiliate = Professional::query()
55	            ->where('handle_lc', $slug)
56	            ->whereNull('deleted_at')
57	            ->first();
58	
59	        if (! $affiliate || $affiliate->status !== 'active') {
60	            return $this->error('Affiliate not found.', 404);
61	        }
62	
63	        $linked = BrandPartnerLink::query()
64	            ->where('brand_professional_id', $integration->professional_id)
65	            ->where('affiliate_professional_id', $affiliate->id)
66	            ->exists();
67	
68	        if (! $linked) {
69	            return $this->error('Affiliate not found.', 404);
70	        }
71	
72	        $site = Site::where('professional_id', $affiliate->id)->first();
73	
74	        // Preload the site's section blocks once — every envelope helper reads
75	        // `is_active` off this collection instead of issuing one exists query
76	        // per section. Keyed by block_type for O(1) lookups.
77	        $sections = $site
78	            ? $site->sectionBlocks()->whereNull('deleted_at')->get()->keyBy('block_type')
79	            : collect();
80	
81	        // Booking data is needed both as its own section and for synthesizing
82	        // a link into the links list, so compute it once and pass the result
83	        // into getAffiliateLinks().
84	        $booking = $this->getAffiliateBooking($site, $sections);
85	
86	        return $this->success([
87	            'affiliate_id' => (string) $affiliate->id,
88	            'name' => $affiliate->display_name,
89	            'slug' => $affiliate->handle,
90	            'gallery' => $this->getAffiliateGallery($site, $sections),
91	            // Content pool — no section-level gate in the dashboard, so no
92	            // envelope. Hydrogen merges these over brand defaults.
93	            'content_images' => $this->getAffiliateContent($site),
94	            'links' => $this->getAffiliateLinks($site, $booking),
95	            'bio' => $this->getAffiliateBio($affiliate, $sections),
96	            'document' => $this->getAffiliateDocument($site),
97	            'newsletter' => $this->getAffiliateNewsletter($sections),
98	            'services' => $this->getAffiliateServices($site, $affiliate->id, $sections),
99	            'booking' => $booking,
100	            // Shop has no content envelope (products come from Shopify), but
101	            // the block_id is needed so Hydrogen can fire click tracking when
102	            // the visitor opens the shop card.
103	            'shop' => $this->sectionEnvelope($sections, 'shop', fn() => null),
104	        ]);
105	    }
106	
107	    /**
108	     * Returns affiliate services for the Hydrogen "Services & Pricing" section.
109	     * Standalone endpoint kept for back-compat / lazy fetches; the same shape
110	     * also appears inside show() under the `services` envelope's `data`.
111	     */
112	    public function services(Request $request): JsonResponse
113	    {
114	        $validator = Validator::make($request->query(), [
115	            'shop_domain' => ['required', 'string', 'max:255'],
116	            'slug' => ['required', 'string', 'max:255'],
117	        ]);
118	
119	        if ($validator->fails()) {
120	            throw new ValidationException($validator);
121	        }
122	
123	        $validated = $validator->validated();
124	        $shopDomain = strtolower(trim($validated['shop_domain']));
125	        $slug = strtolower(trim($validated['slug']));
126	
127	        $integration = ProfessionalIntegration::query()
128	            ->where('shopify_shop_domain', $shopDomain)
129	            ->where('provider', ProfessionalIntegration::PROVIDER_SHOPIFY)
130	            ->first();
131	
132	        if (! $integration) {
133	            return $this->error('Brand not found.', 404);
134	        }
135	
136	        $affiliate = Professional::query()
137	            ->where('handle_lc', $slug)
138	            ->whereNull('deleted_at')
139	            ->first();
140	
141	        if (! $affiliate || $affiliate->status !== 'active') {
142	            return $this->error('Affiliate not found.', 404);
143	        }
144	
145	        $linked = BrandPartnerLink::query()
146	            ->where('brand_professional_id', $integration->professional_id)
147	            ->where('affiliate_professional_id', $affiliate->id)
148	            ->exists();
149	
150	        if (! $linked) {
151	            return $this->error('Affiliate not found.', 404);
152	        }
153	
154	        $site = Site::where('professional_id', $affiliate->id)->first();
155	
156	        return $this->success($this->buildServicesData($site, $affiliate->id));
157	    }
158	
159	    // ── Section envelope helper ──────────────────────────────────────────────
160	    //
161	    // Shape: ['state' => 'draft'|'live', 'data' => mixed|null].
162	    // Pass the pre-loaded sections collection so we don't re-query per call.
163	    // If the section row doesn't exist (edge case during rollout) we treat it
164	    // as draft, matching the dashboard's "missing = not yet published" rule.
165	
166	    /**
167	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
168	     * @return array{state: string, data: mixed}
169	     */
170	    private function sectionEnvelope($sections, string $blockType, callable $buildData): array
171	    {
172	        $section = $sections->get($blockType);
173	        $isLive = $section !== null && (bool) $section->is_active;
174	
175	        return [
