184	    /**
185	     * Returns the gallery envelope. When live, `data` is an ordered array of
186	     * `{url, alt_text, caption, kind, poster, duration_ms}` rows covering both
187	     * images and videos (the dashboard unifies them in one grid). Per-row filter
188	     * keeps only ready rows so Hydrogen never sees processing placeholders.
189	     *
190	     * @param  \Illuminate\Support\Collection<string, Block>  $sections
191	     * @return array{state: string, data: array|null}
192	     */
193	    private function getAffiliateGallery(?Site $site, $sections): array
194	    {
195	        return $this->sectionEnvelope($sections, 'gallery', function () use ($site): array {
196	            if (! $site) {
