198	            }
199	
200	            return SiteMedia::query()
201	                ->where('site_id', $site->id)
202	                ->where('pool', SiteMedia::POOL_GALLERY)
203	                ->where('is_active', true)
204	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
205	                ->with('mediaVariants')
206	                ->orderBy('sort_order')
207	                ->get()
208	                ->map(fn (SiteMedia $media) => $this->buildGalleryItem($media))
