215	    /**
216	     * Project a SiteMedia row to the Hydrogen gallery shape. Videos prefer the
217	     * HLS stream URL (plays natively in Safari + hls.js elsewhere) and fall
218	     * back to progressive MP4 variants; images use the optimised WebP.
219	     *
220	     * @return array{url: string, alt_text: string|null, caption: string|null, kind: string, poster: string|null, duration_ms: int|null}|null
221	     */
222	    private function buildGalleryItem(SiteMedia $media): ?array
223	    {
224	        $isVideo = $media->media_type === SiteMedia::MEDIA_TYPE_VIDEO;
225	
226	        if ($isVideo) {
227	            $streams = [];
228	            $variants = [];
229	            $poster = null;
230	            foreach ($media->mediaVariants as $mv) {
231	                if ($mv->artifact_type === 'hls_playlist') {
232	                    $streams[$mv->variant_key] = $mv->url;
233	                } elseif ($mv->artifact_type === 'mp4') {
234	                    $variants[$mv->variant_key] = $mv->url;
235	                } elseif ($mv->artifact_type === 'poster') {
236	                    $poster = $mv->url;
237	                }
238	            }
239	            // Prefer HLS; fall back through progressive MP4 variants to any
240	            // remaining URL. Mirrors Sidest-Hydrogen's pickVideoSrc() order.
241	            $url = $streams['optimized']
242	                ?? $streams['maximized']
243	                ?? $variants['optimized']
244	                ?? $variants['maximized']
245	                ?? $variants['original']
246	                ?? '';
247	
248	            return [
249	                'url' => $url,
250	                'alt_text' => $media->alt_text,
251	                'caption' => $media->caption,
252	                'kind' => 'video',
253	                'poster' => $poster,
254	                'duration_ms' => $media->duration_ms,
255	            ];
256	        }
257	
258	        $variantUrls = $media->variantUrls();
259	        $url = $variantUrls['optimized'] ?? $variantUrls['original'] ?? '';
260	
261	        return [
262	            'url' => $url,
263	            'alt_text' => $media->alt_text,
264	            'caption' => $media->caption,
265	            'kind' => 'image',
266	            'poster' => null,
267	            'duration_ms' => null,
268	        ];
269	    }
