297	
298	    /**
299	     * Returns every live link block the affiliate has, across every category
300	     * (social, content, education, events, custom). Each link is tagged with
301	     * `category` and, for platform-tagged rows, `platform`. Booking is not a
302	     * link block on the dashboard side, but Hydrogen wants to render it
303	     * alongside the other links — when the booking section is live, we
304	     * synthesize a `{category: 'booking'}` row at the end of the list.
305	     *
306	     * @param  array{state: string, data: array|null}  $bookingEnvelope
307	     */
308	    private function getAffiliateLinks(?Site $site, array $bookingEnvelope): array
309	    {
310	        if (! $site) {
311	            return [];
312	        }
313	
314	        $rows = Block::query()
315	            ->where('site_id', $site->id)
316	            ->where('block_group', 'links')
317	            ->where('is_active', true)
318	            ->whereNull('deleted_at')
319	            ->orderBy('sort_order')
320	            ->get()
321	            ->map(function (Block $block): array {
322	                $settings = is_array($block->settings) ? $block->settings : [];
323	                $platform = is_string($settings['platform'] ?? null)
324	                    ? strtolower(trim((string) $settings['platform']))
325	                    : null;
326	                $platform = $platform !== '' ? $platform : null;
327	                // Category lives in settings to avoid a schema change for
328	                // what is effectively a free-form tag. Default to 'custom'
329	                // for older rows that pre-date the category field.
330	                $category = is_string($settings['category'] ?? null)
331	                    ? strtolower(trim((string) $settings['category']))
332	                    : 'custom';
333	
334	                $title = is_string($block->title) ? trim($block->title) : '';
335	                $url = is_string($block->url) ? trim($block->url) : '';
336	
337	                // Resilience: older link rows can have empty title/url at rest
338	                // — settings.platform + settings.handle are the source of truth
339	                // there. Rebuild both from the platform config so the row still
340	                // renders on Hydrogen without requiring a backfill migration.
341	                if (($title === '' || $url === '') && $platform !== null) {
342	                    $config = config("sidest.social_platforms.{$platform}");
343	                    $handle = is_string($settings['handle'] ?? null)
344	                        ? trim((string) $settings['handle'])
345	                        : '';
346	                    if (is_array($config)) {
347	                        if ($title === '' && is_string($config['display_name'] ?? null)) {
348	                            $title = (string) $config['display_name'];
349	                        }
350	                        if ($url === '' && $handle !== '' && is_string($config['url_template'] ?? null)) {
351	                            $url = str_replace('{handle}', $handle, (string) $config['url_template']);
352	                        }
353	                    }
354	                }
355	
356	                return [
357	                    'id' => (string) $block->id,
358	                    'title' => $title,
359	                    'url' => $url,
360	                    'category' => $category !== '' ? $category : 'custom',
361	                    'platform' => $platform,
362	                ];
363	            })
364	            ->filter(fn (array $item) => $item['title'] !== '' && $item['url'] !== '')
365	            ->values()
366	            ->all();
367	
368	        // Append the synthesized booking link when booking is live + resolved.
369	        // Keeping this controller-side means themes have a single list to
370	        // render rather than special-casing booking everywhere.
371	        if ($bookingEnvelope['state'] === 'live' && is_array($bookingEnvelope['data'])) {
372	            $rows[] = [
373	                'title' => (string) ($bookingEnvelope['data']['title'] ?? 'Book now'),
374	                'url' => (string) ($bookingEnvelope['data']['resolved_url'] ?? ''),
375	                'category' => 'booking',
376	                'platform' => is_string($bookingEnvelope['data']['platform'] ?? null)
377	                    ? $bookingEnvelope['data']['platform']
378	                    : null,
379	            ];
380	            // Filter out the booking link if its url ended up empty.
381	            $rows = array_values(array_filter(
382	                $rows,
383	                fn (array $item) => $item['url'] !== '',
384	            ));
385	        }
386	
387	        return $rows;
388	    }
