417	    /**
418	     * Normalise a credential row from the about JSONB column. The dashboard
419	     * sometimes stamps client-side UUIDs; we strip them so the wire shape is
420	     * stable for Hydrogen.
421	     */
422	    private function normaliseCredential($row): ?array
423	    {
424	        if (! is_array($row)) {
425	            return null;
426	        }
427	        $title = trim((string) ($row['title'] ?? ''));
428	        if ($title === '') {
429	            return null;
430	        }
431	
432	        return [
433	            'title' => $title,
434	            'issuer' => trim((string) ($row['issuer'] ?? '')),
435	            'year' => isset($row['year']) && $row['year'] !== '' ? (string) $row['year'] : null,
436	        ];
437	    }
