439	    /**
440	     * Dashboard writes experience as {role, place, start, end, description}.
441	     * Project to the Hydrogen contract {title, organisation, period} so the
442	     * wire shape mirrors credentials and the theme layer doesn't have to know
443	     * about the source schema differences.
444	     */
445	    private function normaliseExperience($row): ?array
446	    {
447	        if (! is_array($row)) {
448	            return null;
449	        }
450	
451	        // Accept both the current dashboard schema (role/place) and the older
452	        // Hydrogen contract names (title/organisation) so pre-migration rows
453	        // don't silently drop.
454	        $title = trim((string) ($row['role'] ?? $row['title'] ?? ''));
455	        if ($title === '') {
456	            return null;
457	        }
458	
459	        $organisation = trim((string) (
460	            $row['place']
461	            ?? $row['organisation']
462	            ?? $row['organization']
463	            ?? ''
464	        ));
465	
466	        $start = isset($row['start']) && $row['start'] !== '' ? (string) $row['start'] : null;
467	        // A null `end` means "currently active" per the dashboard's
468	        // ExperienceEditorModal contract — render as "Current" so the public
469	        // site reads like a CV, not a blank field.
470	        $rawEnd = $row['end'] ?? null;
471	        $end = is_string($rawEnd) && $rawEnd !== '' ? $rawEnd : null;
472	
473	        if ($start !== null) {
474	            $period = $start.' – '.($end ?? 'Current');
475	        } elseif (isset($row['period']) && $row['period'] !== '') {
476	            $period = (string) $row['period'];
477	        } else {
478	            $period = null;
479	        }
480	
481	        return [
482	            'title' => $title,
483	            'organisation' => $organisation,
484	            'period' => $period,
485	        ];
486	    }
