489	
490	    /**
491	     * Document is gated per-row (SiteMedia.is_active), not at the section
492	     * level — the dashboard's Draft/Live toggle writes is_enabled which maps
493	     * directly to SiteMedia.is_active, and there is no separate "documents"
494	     * section block that also needs flipping. If a ready + active row exists
495	     * the envelope is 'live', otherwise 'draft'.
496	     *
497	     * @return array{state: string, data: array|null}
498	     */
499	    private function getAffiliateDocument(?Site $site): array
500	    {
501	        $media = $site
502	            ? SiteMedia::query()
503	                ->where('site_id', $site->id)
504	                ->where('pool', SiteMedia::POOL_DOCUMENTS)
505	                ->where('is_active', true)
506	                ->where('processing_state', SiteMedia::PROCESSING_STATE_READY)
507	                ->orderByDesc('created_at')
508	                ->first()
509	            : null;
510	
511	        if (! $media) {
512	            return ['state' => 'draft', 'data' => null];
513	        }
514	
515	        return [
516	            'state' => 'live',
517	            'data' => [
518	                // Raw id — Hydrogen uses it to build a same-origin proxy URL
519	                // (e.g. /api/document/{id}) so react-pdf can fetch bytes
520	                // without tripping CORS. The absolute download_url below is
521	                // still used by the Download button, which triggers a
522	                // browser navigation and is not subject to CORS.
523	                'id' => (string) $media->id,
524	                'title' => $media->alt_text,
525	                'caption' => $media->caption,
526	                // Absolute URL to the backend download redirect (signed R2
527	                // URL issued server-side) so the Hydrogen payload never
528	                // carries R2 credentials.
529	                'download_url' => url('/api/public/documents/'.$media->id.'/download'),
530	                'mime' => $media->original_mime,
531	                'size_bytes' => $media->original_size_bytes,
532	            ],
533	        ];
534	    }
