30	    public function summary(Request $request): JsonResponse
31	    {
32	        $professional = $this->currentProfessional($request);
33	
34	        $days = (int) $request->query('days', 30);
35	        $days = max(1, min(365, $days));
36	        $groupBy = mb_strtolower(trim((string) $request->query('group_by', 'day')));
37	        $forceHourly = $groupBy === 'hour';
38	
39	        $fromParam = $request->query('from');
40	        $toParam = $request->query('to');
41	
42	        try {
43	            if ($forceHourly && ! $fromParam && ! $toParam) {
44	                $to = Carbon::now()->utc();
45	                $from = $to->copy()->subHours(24)->startOfHour();
46	            } elseif ($fromParam || $toParam) {
47	                $from = $fromParam
48	                    ? Carbon::parse($fromParam)->startOfDay()
49	                    : Carbon::now()->subDays($days)->startOfDay();
50	
51	                $to = $toParam
52	                    ? Carbon::parse($toParam)->endOfDay()
53	                    : Carbon::now()->endOfDay();
54	            } else {
55	                $to = Carbon::now()->endOfDay();
56	                $from = Carbon::now()->subDays($days)->startOfDay();
57	            }
58	        } catch (Throwable $e) {
59	            return $this->error(
60	                'Invalid date range.  Use YYYY-MM-DD for from/to.',
61	                422,
62	                [
63	                    'from' => $fromParam ? ['Invalid date.'] : [],
64	                    'to' => $toParam ? ['Invalid date.'] : [],
65	                ]
66	            );
67	        }
68	
69	        if ($from->gt($to)) {
70	            return $this->error('Invalid date range: from must be before to. ', 422);
71	        }
72	
73	        $site = $professional->site;
74	        if (! $site) {
75	            return $this->error('professional has no site.', 404);
76	        }
77	
78	        $professionalTimezone = trim((string) ($professional->timezone ?? '')) ?: 'UTC';
79	        $hourlyCutoff = now()->utc()->subHours(24);
80	        $useHourlyBuckets = $forceHourly || (
81	            $from->copy()->utc()->gte($hourlyCutoff)
82	            && $to->copy()->utc()->lte(now()->utc()->addMinute())
83	        );
84	
85	        // Version token lets invalidateAnalytics() bust ALL summary keys for this
86	        // professional at once, regardless of date-range or granularity suffix.
