88	            CacheKeyGenerator::analyticsSummaryVersion($professional->id),
89	            0
90	        );
91	
92	        $cacheKey = CacheKeyGenerator::analyticsSummary(
93	            $professional->id,
94	            $from->format('YmdH'),
95	            $to->format('YmdH')
96	        ).':'.($useHourlyBuckets ? 'hour' : 'day').":v{$summaryVersion}";
97	
98	        // Cache for 5 minutes (or longer for historical data)
99	        $cacheTTL = $to->isToday() ? now()->addMinutes(5) : now()->addHours(24);
100	
101	        $data = $this->cacheLock->rememberLocked($cacheKey, $cacheTTL, function () use ($professional, $from, $to, $site, $professionalTimezone, $useHourlyBuckets) {
102	            // All your existing query logic here
103	
104	            // Totals (visits)
105	            $visitsAgg = DB::table('analytics.site_visits')
106	                ->where('professional_id', $professional->id)
107	                ->whereBetween('occurred_at', [$from, $to])
108	                ->selectRaw('COUNT(*) as total_visits')
109	                ->selectRaw('COUNT(DISTINCT COALESCE(visitor_id::text, ip_hash)) as unique_visitors')
110	                ->selectRaw('MAX(occurred_at) as last_visit_at')
111	                ->first();
112	
