599	    /**
600	     * Aggregate commerce KPIs for a window — used for both the current
601	     * period and the equal-length prior period (vs-prior change badges).
602	     *
603	     * Revenue is back-derived from the ledger: amount_cents (commission)
604	     * divided by commission_rate (percent). NULLIF guards rate=0 rows that
605	     * would otherwise divide by zero.
606	     *
607	     * Quantity is summed out of the calculation_metadata JSON bag captured
608	     * by ProcessShopifyOrderWebhookJob — the only place line-item quantity
609	     * lives, since the ledger itself is rolled up to one accrual per line.
610	     *
611	     * @return array{orders:int, cart_adds:int, checkouts:int, commission_cents:int, revenue_cents:int, avg_order_cents:int, avg_order_qty:float}
612	     */
613	    private function commerceAggregates(string $professionalId, Carbon $from, Carbon $to): array
614	    {
615	        $cartAdds = (int) DB::table('analytics.cart_events')
616	            ->where('professional_id', $professionalId)
617	            ->where('event_type', 'cart_add')
618	            ->whereBetween('occurred_at', [$from, $to])
619	            ->count();
620	
621	        $checkouts = (int) DB::table('analytics.cart_events')
622	            ->where('professional_id', $professionalId)
623	            ->where('event_type', 'checkout_start')
624	            ->whereBetween('occurred_at', [$from, $to])
625	            ->count();
626	
627	        $orderAgg = DB::table('commerce.commission_ledger_entries')
628	            ->where('affiliate_professional_id', $professionalId)
629	            ->where('entry_type', 'accrual')
630	            ->whereNotNull('shopify_order_id')
631	            ->whereBetween('occurred_at', [$from, $to])
632	            ->selectRaw('
633	                COUNT(DISTINCT shopify_order_id) as orders,
634	                SUM(amount_cents) as commission_cents,
635	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents,
636	                SUM((calculation_metadata->>\'quantity\')::int) as total_qty
637	            ')
638	            ->first();
639	
640	        $orders = (int) ($orderAgg->orders ?? 0);
641	        $commissionCents = (int) round((float) ($orderAgg->commission_cents ?? 0));
642	        $revenueCents = (int) round((float) ($orderAgg->revenue_cents ?? 0));
643	        $totalQty = (int) ($orderAgg->total_qty ?? 0);
644	
645	        $avgOrderCents = $orders > 0 ? (int) round($revenueCents / $orders) : 0;
646	        $avgOrderQty = $orders > 0 ? round($totalQty / $orders, 2) : 0.0;
647	
648	        return [
649	            'orders' => $orders,
650	            'cart_adds' => $cartAdds,
651	            'checkouts' => $checkouts,
652	            'commission_cents' => $commissionCents,
653	            'revenue_cents' => $revenueCents,
654	            'avg_order_cents' => $avgOrderCents,
655	            'avg_order_qty' => $avgOrderQty,
656	        ];
657	    }
