659	    /**
660	     * Commerce timeseries for the area chart — orders / commission / revenue
661	     * grouped by hour or day depending on bucket choice.
662	     *
663	     * @return array{orders_by_day:\Illuminate\Support\Collection, commission_by_day:\Illuminate\Support\Collection, revenue_by_day:\Illuminate\Support\Collection}
664	     */
665	    private function commerceCharts(string $professionalId, Carbon $from, Carbon $to, bool $useHourlyBuckets): array
666	    {
667	        $bucket = $useHourlyBuckets ? "DATE_TRUNC('hour', occurred_at)" : 'DATE(occurred_at)';
668	
669	        $rows = DB::table('commerce.commission_ledger_entries')
670	            ->where('affiliate_professional_id', $professionalId)
671	            ->where('entry_type', 'accrual')
672	            ->whereNotNull('shopify_order_id')
673	            ->whereBetween('occurred_at', [$from, $to])
674	            ->selectRaw("
675	                {$bucket} as bucket,
676	                COUNT(DISTINCT shopify_order_id) as orders,
677	                SUM(amount_cents) as commission_cents,
678	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents
679	            ")
680	            ->groupByRaw($bucket)
681	            ->orderBy('bucket')
682	            ->get();
683	
684	        return [
685	            'orders_by_day' => $rows->map(fn ($r) => [
686	                'bucket' => $r->bucket,
687	                'orders' => (int) $r->orders,
688	            ])->values(),
689	            'commission_by_day' => $rows->map(fn ($r) => [
690	                'bucket' => $r->bucket,
691	                'commission_cents' => (int) round((float) $r->commission_cents),
692	            ])->values(),
693	            'revenue_by_day' => $rows->map(fn ($r) => [
694	                'bucket' => $r->bucket,
695	                'revenue_cents' => (int) round((float) $r->revenue_cents),
696	            ])->values(),
697	        ];
698	    }
699	
700	    /**
701	     * Top products by commission earned in the window.
702	     *
703	     * Reads product title from the calculation_metadata JSON bag (captured
704	     * by ProcessShopifyOrderWebhookJob since the line-item title is the only
705	     * source available without a Shopify Admin call). Older rows pre-dating
706	     * the title capture render with a "Product #{id}" fallback.
707	     */
708	    private function topProducts(string $professionalId, Carbon $from, Carbon $to): \Illuminate\Support\Collection
709	    {
710	        return DB::table('commerce.commission_ledger_entries')
711	            ->where('affiliate_professional_id', $professionalId)
712	            ->where('entry_type', 'accrual')
713	            ->whereNotNull('shopify_order_id')
714	            ->whereBetween('occurred_at', [$from, $to])
715	            ->whereRaw("calculation_metadata->>'product_id' IS NOT NULL")
716	            ->selectRaw("
717	                calculation_metadata->>'product_id' as product_id,
718	                MAX(calculation_metadata->>'product_title') as product_title,
719	                COUNT(DISTINCT shopify_order_id) as orders,
720	                SUM(amount_cents) as commission_cents,
721	                SUM(amount_cents * 100.0 / NULLIF(commission_rate, 0)) as revenue_cents
722	            ")
723	            ->groupByRaw("calculation_metadata->>'product_id'")
724	            ->orderByDesc('commission_cents')
725	            ->limit(8)
726	            ->get()
727	            ->map(fn ($r) => [
728	                'product_id' => (string) $r->product_id,
729	                'title' => (string) ($r->product_title ?? 'Product #'.substr((string) $r->product_id, -6)),
730	                'orders' => (int) $r->orders,
731	                'commission_cents' => (int) round((float) $r->commission_cents),
732	                'revenue_cents' => (int) round((float) $r->revenue_cents),
733	            ])
734	            ->values();
735	    }
736	}
