16	class BrandCommerceAnalyticsController extends ApiController
17	{
18	    use ResolveCurrentProfessional;
19	
20	    public function __construct(private CacheLockService $cacheLock) {}
21	
22	    /**
23	     * Brand's commerce performance overview.
24	     * Brand totals use brand_metrics_hourly for last 24h, brand_metrics_daily for older ranges.
25	     * Per-affiliate breakdown and commission summary always use their daily tables (no hourly equivalent).
26	     *
27	     * @return JsonResponse{ data: { range, granularity, totals, timeseries, affiliates, commission_summary } }
28	     */
29	    public function overview(Request $request): JsonResponse
30	    {
31	        $professional = $this->currentProfessional($request);
32	        $professionalId = (string) $professional->id;
33	
34	        $filters = $this->resolveFilters($request);
35	        $cacheKey = CacheKeyGenerator::brandCommerceAnalytics($professionalId, $filters['from'], $filters['to']);
36	
37	        return $this->success($this->cacheLock->rememberLocked($cacheKey, now()->addMinutes(5), function () use ($professionalId, $filters): array {
38	            [$totals, $timeseries, $currencyCode] = $filters['use_hourly']
39	                ? $this->buildHourlyTotals($professionalId, $filters)
40	                : $this->buildDailyTotals($professionalId, $filters);
41	
42	            // Per-affiliate commerce breakdown — daily only (no hourly equivalent table)
43	            $affiliateRows = DB::table('analytics.brand_affiliate_daily')
44	                ->where('brand_professional_id', $professionalId)
45	                ->whereBetween('day', [$filters['from'], $filters['to']])
46	                ->get()
47	                ->groupBy('affiliate_professional_id');
48	
49	            // Per-affiliate page views — pulled from site_metrics_daily for
50	            // every linked affiliate of this brand. Joined here (not via
51	            // a backend SQL JOIN) so the existing brand_affiliate_daily
52	            // groupBy stays simple. Only affiliates with at least one
53	            // BrandPartnerLink to this brand are included; the LEFT JOIN
54	            // to brand_partner_links keeps the query brand-scoped without
55	            // pulling in every site on the platform.
56	            $linkedAffiliateIds = DB::table('brand.brand_partner_links')
57	                ->where('brand_professional_id', $professionalId)
58	                ->pluck('affiliate_professional_id');
59	
60	            // Skip identity and pageview lookups when there are no linked
61	            // affiliates — avoids unnecessary DB round-trips and keeps the
62	            // PostgreSQL-specific ::int cast out of the query entirely.
63	            $identityRows = collect();
64	            $pageviewByAffiliate = collect();
65	
66	            if ($linkedAffiliateIds->isNotEmpty()) {
67	                // Display labels keyed by professional id so the leaderboard
68	                // can render real names instead of UUIDs.
69	                $identityRows = DB::table('core.professionals')
70	                    ->whereIn('id', $linkedAffiliateIds)
71	                    ->whereNull('deleted_at')
72	                    ->select('id', 'display_name', 'first_name', 'last_name', 'handle')
73	                    ->get()
74	                    ->keyBy('id');
75	
76	                $pageviewByAffiliate = DB::table('analytics.site_metrics_daily')
77	                    ->whereIn('professional_id', $linkedAffiliateIds)
78	                    ->whereBetween('day', [$filters['from'], $filters['to']])
79	                    ->select(
80	                        'professional_id',
81	                        DB::raw('SUM(visits_count)::int as visits_count'),
82	                        DB::raw('SUM(unique_visitors)::int as unique_visitors'),
83	                    )
84	                    ->groupBy('professional_id')
85	                    ->get()
86	                    ->keyBy('professional_id');
87	            }
88	
89	            $affiliates = $affiliateRows->map(function ($rows, $affiliateId) use ($pageviewByAffiliate, $identityRows) {
90	                $affiliateCurrency = $rows->sortByDesc('orders_count')->first()?->currency_code ?? 'AUD';
91	                $primary = $rows->filter(fn ($r) => $r->currency_code === $affiliateCurrency);
92	                $views = $pageviewByAffiliate->get($affiliateId);
93	                $orders = (int) $primary->sum('orders_count');
94	                $visits = (int) ($views->visits_count ?? 0);
95	                // Conversion = orders / unique_visitors (more meaningful than
96	                // raw visits which can include the same browser bouncing).
97	                // Falls back to 0 when there's no traffic at all.
98	                $uniqueVisitors = (int) ($views->unique_visitors ?? 0);
99	                $conversionRate = $uniqueVisitors > 0
100	                    ? round(($orders / $uniqueVisitors) * 100, 2)
101	                    : 0.0;
102	
103	                // Resolve affiliate label: prefer first+last → display_name
104	                // → handle. Pure UUID is a last resort so the dashboard
105	                // never has to render a 36-char hex id in the table.
106	                $identity = $identityRows->get($affiliateId);
107	                $fullName = trim(implode(' ', array_filter([$identity?->first_name, $identity?->last_name])));
108	                $displayName = $fullName !== ''
109	                    ? $fullName
110	                    : ($identity?->display_name ?? $identity?->handle ?? 'Affiliate');
111	
112	                return [
113	                    'affiliate_professional_id' => $affiliateId,
114	                    'affiliate_display_name' => $displayName,
115	                    'affiliate_handle' => $identity?->handle,
116	                    'orders_count' => $orders,
117	                    'gross_cents' => (int) $primary->sum('gross_cents'),
118	                    'net_cents' => (int) $primary->sum('net_cents'),
119	                    'commission_net_cents' => (int) $primary->sum('commission_net_cents'),
120	                    'customers_count' => (int) $primary->sum('customers_count'),
121	                    'page_views' => $visits,
122	                    'unique_visitors' => $uniqueVisitors,
123	                    'conversion_rate_percent' => $conversionRate,
124	                    'currency_code' => strtoupper($affiliateCurrency),
125	                ];
126	            })->values()->all();
127	
128	            // Brand-level page-view total — sum across every linked
129	            // affiliate for the requested window. Surfaces as a KPI on
130	            // the brand analytics page ("Page views across all your
131	            // affiliates").
132	            $totalPageviews = (int) $pageviewByAffiliate->sum('visits_count');
133	            $totalUniqueVisitors = (int) $pageviewByAffiliate->sum('unique_visitors');
134	
135	            // Commission summary — daily only
136	            $commissionRows = DB::table('analytics.brand_commission_daily')
137	                ->where('brand_professional_id', $professionalId)
138	                ->whereBetween('day', [$filters['from'], $filters['to']])
139	                ->get()
140	                ->groupBy('payout_status');
141	
142	            $commissionCurrencyCode = $commissionRows->flatten(1)->first()?->currency_code ?? $currencyCode;
143	
144	            $commissionSummary = [
145	                'pending_cents' => (int) ($commissionRows->get('pending')?->sum('net_outstanding_cents') ?? 0),
146	                'approved_cents' => (int) ($commissionRows->get('approved')?->sum('net_outstanding_cents') ?? 0),
147	                'paid_cents' => (int) ($commissionRows->get('paid')?->sum('payout_cents') ?? 0),
148	                'reversed_cents' => (int) ($commissionRows->get('reversed')?->sum('reversal_cents') ?? 0),
149	                'currency_code' => strtoupper($commissionCurrencyCode),
150	            ];
151	
152	            // Layer the page-view totals onto the existing totals block so
153	            // the dashboard can show "X orders / $Y gross / Z page views"
154	            // as a coherent KPI strip.
155	            $totals['page_views'] = $totalPageviews;
156	            $totals['unique_visitors'] = $totalUniqueVisitors;
157	
158	            return [
159	                'range' => ['from' => $filters['from'], 'to' => $filters['to']],
160	                'granularity' => $filters['use_hourly'] ? 'hour' : 'day',
161	                'totals' => $totals,
162	                'timeseries' => $timeseries,
163	                'affiliates' => $affiliates,
164	                'commission_summary' => $commissionSummary,
165	            ];
166	        }));
167	    }
