169	    /** @return array{0: array, 1: array, 2: string} [totals, timeseries, currencyCode] */
170	    private function buildDailyTotals(string $professionalId, array $filters): array
171	    {
172	        $rows = DB::table('analytics.brand_metrics_daily')
173	            ->where('brand_professional_id', $professionalId)
174	            ->whereBetween('day', [$filters['from'], $filters['to']])
175	            ->get();
176	
177	        $currencyCode = $rows->sortByDesc('orders_count')->first()?->currency_code ?? 'AUD';
178	        $primary = $rows->filter(fn ($r) => $r->currency_code === $currencyCode);
179	
180	        $totals = [
181	            'orders_count' => (int) $primary->sum('orders_count'),
182	            'gross_cents' => (int) $primary->sum('gross_cents'),
183	            'refunded_cents' => (int) $primary->sum('refunded_cents'),
184	            'net_cents' => (int) $primary->sum('net_cents'),
185	            'currency_code' => strtoupper($currencyCode),
186	        ];
187	
188	        $timeseries = $primary->sortBy('day')->map(fn ($row) => [
189	            'bucket' => (string) $row->day,
190	            'orders_count' => (int) $row->orders_count,
191	            'gross_cents' => (int) $row->gross_cents,
192	            'net_cents' => (int) $row->net_cents,
193	        ])->values()->all();
