198	    /** @return array{0: array, 1: array, 2: string} [totals, timeseries, currencyCode] */
199	    private function buildHourlyTotals(string $professionalId, array $filters): array
200	    {
201	        $rows = DB::table('analytics.brand_metrics_hourly')
202	            ->where('brand_professional_id', $professionalId)
203	            ->where('hour_start', '>=', $filters['hourly_from'])
204	            ->where('hour_start', '<', $filters['hourly_to'])
205	            ->get();
206	
207	        $currencyCode = $rows->sortByDesc('orders_count')->first()?->currency_code ?? 'AUD';
208	        $primary = $rows->filter(fn ($r) => $r->currency_code === $currencyCode);
209	
210	        $totals = [
211	            'orders_count' => (int) $primary->sum('orders_count'),
212	            'gross_cents' => (int) $primary->sum('gross_cents'),
213	            'refunded_cents' => (int) $primary->sum('refunded_cents'),
214	            'net_cents' => (int) $primary->sum('net_cents'),
215	            'currency_code' => strtoupper($currencyCode),
216	        ];
217	
218	        $timeseries = $primary->sortBy('hour_start')->map(fn ($row) => [
219	            'bucket' => Carbon::parse($row->hour_start)->toIso8601String(),
220	            'orders_count' => (int) $row->orders_count,
221	            'gross_cents' => (int) $row->gross_cents,
222	            'net_cents' => (int) $row->net_cents,
223	        ])->values()->all();
224	
225	        return [$totals, $timeseries, $currencyCode];
226	    }
227	
228	    private function resolveFilters(Request $request): array
229	    {
230	        $validator = Validator::make($request->query(), [
231	            'from' => ['sometimes', 'date_format:Y-m-d'],
232	            'to' => ['sometimes', 'date_format:Y-m-d'],
233	            'days' => ['sometimes', 'integer', 'min:1', 'max:3650'],
234	        ]);
235	
236	        if ($validator->fails()) {
237	            throw new ValidationException($validator);
238	        }
239	
240	        $validated = $validator->validated();
241	        $hasFrom = isset($validated['from']);
242	        $hasTo = isset($validated['to']);
243	
244	        if ($hasFrom xor $hasTo) {
245	            throw ValidationException::withMessages([
246	                'from' => ['from and to must be provided together.'],
247	                'to' => ['from and to must be provided together.'],
248	            ]);
249	        }
250	
251	        if ($hasFrom && $hasTo) {
252	            $from = Carbon::createFromFormat('Y-m-d', (string) $validated['from']);
253	            $to = Carbon::createFromFormat('Y-m-d', (string) $validated['to']);
254	
255	            if ($from->gt($to)) {
256	                throw ValidationException::withMessages([
257	                    'from' => ['from must be before to.'],
258	                ]);
259	            }
260	
261	            return $this->buildFilterContext($from->toDateString(), $to->toDateString());
262	        }
263	
264	        $days = max(1, min(365, (int) ($validated['days'] ?? 30)));
265	
266	        return $this->buildFilterContext(
267	            now()->subDays($days - 1)->toDateString(),
268	            now()->toDateString()
269	        );
270	    }
271	
272	    private function buildFilterContext(string $from, string $to): array
273	    {
274	        $cutoff = now()->utc()->subHours(24)->startOfHour();
275	        $fromUtc = Carbon::parse($from)->utc()->startOfDay();
276	        $toUtc = Carbon::parse($to)->utc()->endOfDay();
277	
278	        // Use hourly table when the entire range falls within the last 24h.
279	        $useHourly = $fromUtc->gte($cutoff) && $toUtc->lte(now()->utc()->addMinute());
280	
281	        return [
282	            'from' => $from,
283	            'to' => $to,
284	            'use_hourly' => $useHourly,
285	            'hourly_from' => $cutoff,
286	            'hourly_to' => now()->utc()->addMinute(),
287	        ];
288	    }
289	}
