3	namespace App\Http\Controllers\Api;
4	
5	use App\Http\Controllers\Controller;
6	use Illuminate\Http\JsonResponse;
7	
8	// V2: Abstract base controller. Provides success(), error(), and paginated() response helpers for all API endpoints.
9	abstract class ApiController extends Controller
10	{
11	    /**
12	     * Return success response with data.
13	     */
14	    protected function success($data = null, int $status = 200): JsonResponse
15	    {
16	        return response()->json($data, $status);
17	    }
18	
19	    /**
20	     * Return error response with message.
21	     */
22	    protected function error(string $message, int $status = 400, array $errors = []): JsonResponse
23	    {
24	        $response = ['message' => $message];
25	
26	        if (! empty($errors)) {
27	            $response['errors'] = $errors;
28	        }
29	
30	        return response()->json($response, $status);
31	    }
32	
33	    /**
34	     * Return paginated response.
35	     */
36	    protected function paginated($paginator, string $dataKey = 'data'): JsonResponse
37	    {
38	        return response()->json([
39	            $dataKey => $paginator->items(),
40	            'meta' => [
41	                'current_page' => $paginator->currentPage(),
42	                'per_page' => $paginator->perPage(),
43	                'total' => $paginator->total(),
44	                'last_page' => $paginator->lastPage(),
45	                'next_page_url' => $paginator->nextPageUrl(),
46	                'prev_page_url' => $paginator->previousPageUrl(),
47	            ],
48	        ]);
49	    }
50	}
